    if (tabs.has(id)) emit({ type: "shown", ...key, shown });
  };

  const handleCommandLine = (line: string, epoch="fd", current:()=>boolean=()=>true) =>
    Effect.sync(() => {
      if(transportEpoch!==epoch || !current())return;
      const command = decodeCommand(line);
      if (Option.isNone(command)) return;
      if (command.value.type === "turn") {
        if (command.value.active) agentTurns.add(command.value.threadId);
        else endAgentTurn(command.value.threadId);
