        const { threadId, tabId, phase, x, y } = command.value;
        runFork(Effect.suspend(()=>transportEpoch===epoch && tabs.get(keyOf(tab.key))===tab && current() ? PubSub.publish(pointers, { key: { threadId, tabId }, phase, x, y }) : Effect.void));
