      },
      { discard: true },
    );
  });

  return DesktopBrowserHost.of({
    pointers: Stream.fromPubSub(pointers),
    painting: Stream.fromPubSub(painting),
    // Subscribes before announcing, so no attach falls between the two.
    events: Stream.unwrap(
      Effect.gen(function* () {
        const subscription = yield* PubSub.subscribe(outbox);
        yield* announceAll;
        return Stream.fromSubscription(subscription);
      }),
    ).pipe(Stream.map((event) => lineEncoder.encode(`${encodeEvent(event)}\n`))),
    handleCommandLine,
    beginTransport:(epoch:string)=>{transportEpoch=epoch;agentTurns.clear();for(const tab of tabs.values())dropRelay(tab);},
    endTransport:(epoch:string)=>{if(transportEpoch!==epoch)return;transportEpoch=null;agentTurns.clear();for(const tab of tabs.values())dropRelay(tab);},
    attach,
    detach,
    setShown,
    placeDownload,
    humanStartedDownload,
  });
});

